// This file is generated by AI.

// 应用内「把一个文件路径拖进编辑器」的拖拽。
//
// 源: 场景/资源浏览器的文件行、选项卡栏的选项卡 (场景/资源/配置卡)。目标: 编辑器 (Monaco),
// 落下去等于执行一次「复制相对路径」——插入的文本与那一项菜单**完全一样**, 由调用方算好传进来。
//
// ⚠️ 为什么是**指针事件**而不是 HTML5 DnD: `tauri.conf.json` 没有关掉 `dragDropEnabled`,
// 而 Tauri 一旦接管系统拖放, 页面内的 HTML5 `dragstart` / `drop` 在 Windows 上就不再触发
// (见 `@tauri-apps/api` 里 `dragDropEnabled` 的说明)。`ui/TabStrip.svelte` 的选项卡排序
// 也是同一个原因改用指针事件的。**别把这里改回 `draggable` + `dragstart`**: 那会静默失效,
// 没有任何报错。
//
// 落点由目标自己登记 (`registerPathDropTarget`), 这里只负责三件与具体界面无关的事:
// 越过阈值才算拖拽、把"指针下面是哪个落点"算出来、以及拖拽结束后吞掉紧跟的那一次 click。

/** 判定为拖拽的位移阈值 (px); 与选项卡排序共用同一手感 */
export const PATH_DRAG_THRESHOLD = 6;

/** 落点登记用的属性名: 命中检测靠它从最内层节点向上找已登记的落点 */
const DROP_ATTR = 'data-path-drop';

export interface DragPoint {
  x: number;
  y: number;
}

/**
 * 拖拽中的公开状态 (组件读它来画浮层 / 给落点加高亮)。
 *
 * `active` 只在**真正拖起来之后**为真 —— 指针刚按下时还是普通的单击, 不能提前画浮层。
 */
export const pathDrag = $state({
  active: false,
  /** 松手时要插入的文本 */
  text: '',
  x: 0,
  y: 0,
  /** 指针下能接收路径的编辑器元素; 用来给那个编辑器加高亮 */
  target: null as HTMLElement | null,
});

/** 落点的插入实现; 返回"是否消费了这次放下"(只读编辑器等情形返回 false) */
export type PathInsertHandler = (text: string, point: DragPoint) => boolean;

/** 落点能做的事: 落下时插入, 指针经过时给提示 (编辑器用它画"插入到这里"的竖线光标) */
export interface PathDropTarget {
  insert: PathInsertHandler;
  /**
   * 指针经过本落点 (含同一个落点内的每次移动)。
   *
   * 参数为 `null` 表示"已经离开" —— 提示必须收回, 否则它会一直停在屏幕上。
   * 返回 `false` 表示**这次放不下来** (只读编辑器之类): 落点高亮不会亮, 用户不会以为能插。
   */
  hover?: (point: DragPoint | null) => boolean;
}

const targets = new WeakMap<Element, PathDropTarget>();

/**
 * 当前"指针在哪个落点上"。
 *
 * 不是响应式状态, 只用于**成对**通知落点: 进入时开提示、离开时关。只在 `hover` 里画而没人
 * 负责收, 提示就会残留 (拖拽结束、指针移出编辑器、落点被注销都会漏)。
 */
let hovered: { element: HTMLElement; target: PathDropTarget } | null = null;

function releaseHover(): void {
  hovered?.target.hover?.(null);
  hovered = null;
}

/** 登记一个能接收路径的落点。返回注销函数 —— 组件销毁时必须调用, 否则会留下野落点。 */
export function registerPathDropTarget(element: HTMLElement, target: PathDropTarget): () => void {
  targets.set(element, target);
  element.setAttribute(DROP_ATTR, '');
  return () => {
    // 注销时若正悬停在它上面, 先把提示收掉 (组件销毁后没人能再清它)
    if (hovered?.element === element) releaseHover();
    targets.delete(element);
    element.removeAttribute(DROP_ATTR);
  };
}

/**
 * 指针下的落点。
 *
 * 用 `closest` 而不是 `matches`: 指针通常落在 Monaco 内部的某个子节点上, 只测最内层节点会
 * 永远找不着宿主元素。
 */
export function findPathDropTarget(x: number, y: number): { element: HTMLElement; target: PathDropTarget } | null {
  const hit = document.elementFromPoint(x, y);
  const element = hit instanceof Element ? hit.closest<HTMLElement>(`[${DROP_ATTR}]`) : null;
  if (!element) return null;
  const target = targets.get(element);
  return target ? { element, target } : null;
}

/** 把文本插进指针下的编辑器; 返回是否真的落到了某个落点上。 */
export function dropPathAt(text: string, point: DragPoint): boolean {
  const target = findPathDropTarget(point.x, point.y);
  if (!target) return false;
  return target.target.insert(text, point);
}

/** 指针移动时同步落点提示 (离开 / 进入 / 同一个落点内移动都只走这一条)。 */
function syncHover(point: DragPoint): void {
  const found = findPathDropTarget(point.x, point.y);
  if (hovered?.element !== found?.element) {
    releaseHover();
    hovered = found;
  }
  const accepted = found ? (found.target.hover?.(point) ?? true) : false;
  pathDrag.target = accepted ? (found?.element ?? null) : null;
}

/** 更新拖拽浮层与落点提示 (选项卡栏自己管拖拽流程时用这一对, 不用 `beginPathDrag`)。 */
export function previewPathDrag(text: string, point: DragPoint): void {
  pathDrag.active = true;
  pathDrag.text = text;
  pathDrag.x = point.x;
  pathDrag.y = point.y;
  setDraggingCursor(true);
  syncHover(point);
}

/** 收掉浮层与落点提示 (不改指针事件监听) */
export function clearPathDrag(): void {
  pathDrag.active = false;
  pathDrag.text = '';
  pathDrag.target = null;
  setDraggingCursor(false);
  releaseHover();
}

/**
 * 拖拽期间的鼠标指针。
 *
 * 挂在 `body` 上而不是靠落点自己写 `cursor`: 指针被源元素捕获着, 而且全程跨着好几个元素,
 * 逐个设置必然有漏 —— 漏掉的那一段指针会变回箭头, 看起来像"拖丢了"。
 */
function setDraggingCursor(dragging: boolean): void {
  if (typeof document === 'undefined') return;
  document.body.classList.toggle('path-dragging', dragging);
}

/** 是否已经越过拖拽阈值 (任一轴达到阈值, 与选项卡排序一致)。 */
export function pathDragReachedThreshold(
  origin: DragPoint,
  point: DragPoint,
  threshold = PATH_DRAG_THRESHOLD
): boolean {
  return Math.abs(point.x - origin.x) >= threshold || Math.abs(point.y - origin.y) >= threshold;
}

/**
 * 拖拽刚结束时紧跟的那一次 click 要吞掉。
 *
 * 源元素上本来就有 click 处理器 (打开文件 / 激活选项卡), 而指针拖拽结束后浏览器照例会派发
 * click —— 不吞的话"把某个文件拖进编辑器"会顺手把它也打开, 或者把用户刚拖进去的那一页切走。
 * 标记在下一次任务里自动复位: click 与 pointerup 在同一个任务里接连派发, 不用手工"消费"。
 */
let suppressedClick = false;

export function suppressClickAfterDrag(): void {
  suppressedClick = true;
  setTimeout(() => {
    suppressedClick = false;
  }, 0);
}

/** click 处理器里读它: 这次点击是不是某次拖拽的残余。 */
export function isClickAfterDragSuppressed(): boolean {
  return suppressedClick;
}

interface DragSession {
  text: string;
  pointerId: number;
  origin: DragPoint;
  active: boolean;
  /** 捕获指针的元素 (指针拖出窗口后仍能收到 pointerup) */
  capture: Element | null;
}

let session: DragSession | null = null;

/**
 * 开始一次可能的拖拽 (在源元素的 `pointerdown` 里调用)。
 *
 * 返回后**不阻止**单击: 没越过阈值就什么都不发生, click 照常派发给源元素。
 */
export function beginPathDrag(event: PointerEvent, text: string): void {
  if (event.button !== 0 || !text.trim()) return;
  endSession(); // 上一次没收尾的 (pointerup 在窗口外丢失) 先清掉

  const capture = event.currentTarget instanceof Element ? event.currentTarget : null;
  session = {
    text,
    pointerId: event.pointerId,
    origin: { x: event.clientX, y: event.clientY },
    active: false,
    capture,
  };
  try {
    capture?.setPointerCapture(event.pointerId);
  } catch {
    // 指针已经释放 (或元素不在文档里): 拿不到捕获也能拖, 只是拖出窗口后收不到 up
  }

  window.addEventListener('pointermove', onPointerMove);
  window.addEventListener('pointerup', onPointerUp);
  window.addEventListener('pointercancel', cancelPathDrag);
  window.addEventListener('keydown', onKeyDown, true);
  window.addEventListener('blur', cancelPathDrag);
}

function onPointerMove(event: PointerEvent): void {
  const current = session;
  if (!current || event.pointerId !== current.pointerId) return;
  const point: DragPoint = { x: event.clientX, y: event.clientY };
  if (!current.active) {
    if (!pathDragReachedThreshold(current.origin, point)) return;
    current.active = true;
  }
  previewPathDrag(current.text, point);
}

function onPointerUp(event: PointerEvent): void {
  const current = session;
  if (!current || event.pointerId !== current.pointerId) return;
  const point: DragPoint = { x: event.clientX, y: event.clientY };
  // 先收尾再动: 插入文本会改文档, 不该在这次拖拽的监听还挂着的时候发生
  const dropped = current.active;
  endSession();
  if (!dropped) return; // 没越过阈值 = 一次普通单击
  suppressClickAfterDrag();
  dropPathAt(current.text, point);
}

/** Esc 取消 (与"关掉浮层"一致的手势) */
function onKeyDown(event: KeyboardEvent): void {
  if (event.key !== 'Escape') return;
  cancelPathDrag();
}

function cancelPathDrag(): void {
  endSession();
}

function endSession(): void {
  const current = session;
  session = null;
  if (current?.capture) {
    try {
      current.capture.releasePointerCapture(current.pointerId);
    } catch {
      // 已经释放 / 指针已结束: 无需处理
    }
  }
  window.removeEventListener('pointermove', onPointerMove);
  window.removeEventListener('pointerup', onPointerUp);
  window.removeEventListener('pointercancel', cancelPathDrag);
  window.removeEventListener('keydown', onKeyDown, true);
  window.removeEventListener('blur', cancelPathDrag);
  clearPathDrag();
}
